func newRequest(server, method, path string, body io.Reader) (*http.Request, error) {
	serverURL, err := url.Parse(server)
	if err != nil {
		return nil, err
	}
	operationPath := path
	if !strings.HasPrefix(operationPath, "/") {
		operationPath = "/" + operationPath
	}
	queryURL := serverURL.JoinPath(operationPath)
	req, err := http.NewRequest(method, queryURL.String(), body)
	if err != nil {
		return nil, err
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	return req, nil
}
